package com.ejemplo.msa.security;
import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig { @Bean SecurityFilterChain security(HttpSecurity http)throws Exception { return http.csrf(c->c.disable()).formLogin(f->f.disable()).httpBasic(b->b.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.anyRequest().hasRole("ADMIN")).addFilterBefore(new JwtAuthenticationFilter(),UsernamePasswordAuthenticationFilter.class).build(); } }
